                    threepidInvite={undefined as any}
                    resizeNotifier={new ResizeNotifier()}
                    forceTimeline={false}
                    onRegistered={jest.fn()}
                />
            </SDKContext.Provider>,
            { wrapper: TooltipProvider },
        );
        await flushPromises();
        return roomView;
